package com.greenpulse.controller;
import com.greenpulse.common.ApiEnvelope;import com.greenpulse.domain.*;import com.greenpulse.repository.*;import com.greenpulse.service.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1")
public class ResourceController {
 private final OrganizationRepository orgs;private final BuildingRepository buildings;private final FactorRepository factors;private final CurrentUser current;
 public ResourceController(OrganizationRepository o,BuildingRepository b,FactorRepository f,CurrentUser c){orgs=o;buildings=b;factors=f;current=c;}
 record OrgInput(@NotBlank String name,String type,String address,String country,String state){}
 record BuildingInput(@NotNull Long organizationId,@NotBlank String name,String type,String location,BigDecimal areaSqft,Integer floors){}
 record FactorInput(@NotBlank String region,@DecimalMin("0.0") BigDecimal factor,@NotBlank String unit,@NotNull LocalDate effectiveFrom,LocalDate effectiveTo,@NotBlank String source){}
 @GetMapping("/organizations") public ApiEnvelope<?> organizations(){var u=current.get();var all=orgs.findAll().stream().filter(o->current.isSuper(u)||Objects.equals(o.getId(),current.org(u))).toList();return ApiEnvelope.ok("Organizations",all.stream().map(this::orgDto).toList());}
 @PostMapping("/organizations") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public ApiEnvelope<?> createOrg(@Valid @RequestBody OrgInput x){if(!current.isSuper(current.get()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Only a super administrator may create an organization");Organization o=new Organization();o.setName(x.name());o.setType(x.type());o.setAddress(x.address());o.setCountry(x.country());o.setState(x.state());return ApiEnvelope.ok("Organization created",orgDto(orgs.save(o)));}
 @GetMapping("/organizations/{id}") public ApiEnvelope<?> getOrg(@PathVariable Long id){var u=current.get();var o=orgs.findById(id).filter(x->current.isSuper(u)||Objects.equals(x.getId(),current.org(u))).orElseThrow(()->new NoSuchElementException("Organization not found"));return ApiEnvelope.ok("Organization",orgDto(o));}
 @GetMapping({"/buildings","/organizations/{organizationId}/buildings"}) public ApiEnvelope<?> buildingList(@PathVariable(required=false) Long organizationId){var u=current.get();var list=buildings.scoped(current.isSuper(u),current.org(u)).stream().filter(b->organizationId==null||Objects.equals(b.getOrganization().getId(),organizationId)).toList();return ApiEnvelope.ok("Buildings",list.stream().map(this::buildingDto).toList());}
 @PostMapping("/buildings") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public ApiEnvelope<?> createBuilding(@Valid @RequestBody BuildingInput x){var u=current.get();var org=orgs.findById(x.organizationId()).filter(o->current.isSuper(u)||Objects.equals(o.getId(),current.org(u))).orElseThrow(()->new NoSuchElementException("Organization not found"));Building b=new Building();b.setOrganization(org);b.setName(x.name());b.setType(x.type());b.setLocation(x.location());b.setAreaSqft(x.areaSqft());b.setFloors(x.floors());return ApiEnvelope.ok("Building created",buildingDto(buildings.save(b)));}
 @GetMapping("/buildings/{id}") public ApiEnvelope<?> getBuilding(@PathVariable Long id){return ApiEnvelope.ok("Building",buildingDto(scopedBuilding(id)));}
 private Building scopedBuilding(Long id){var u=current.get();return buildings.findScoped(id,current.isSuper(u),current.org(u)).orElseThrow(()->new NoSuchElementException("Building not found"));}
 @GetMapping("/carbon/emission-factors") public ApiEnvelope<?> factorList(){return ApiEnvelope.ok("Emission factors",factors.findAllByOrderByEffectiveFromDesc());}
 @PostMapping("/carbon/emission-factors") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public ApiEnvelope<?> createFactor(@Valid @RequestBody FactorInput x){var f=new EmissionFactor();factorSet(f,x);return ApiEnvelope.ok("Emission factor created",factors.save(f));}
 @PutMapping("/carbon/emission-factors/{id}") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public ApiEnvelope<?> updateFactor(@PathVariable Long id,@Valid @RequestBody FactorInput x){var f=factors.findById(id).orElseThrow(()->new NoSuchElementException("Emission factor not found"));factorSet(f,x);return ApiEnvelope.ok("Emission factor updated",factors.save(f));}
 private void factorSet(EmissionFactor f,FactorInput x){f.setRegion(x.region());f.setFactor(x.factor());f.setUnit(x.unit());f.setEffectiveFrom(x.effectiveFrom());f.setEffectiveTo(x.effectiveTo());f.setSource(x.source());}
 private Map<String,Object> orgDto(Organization o){return Map.of("id",o.getId(),"name",o.getName(),"type",o.getType()==null?"":o.getType(),"address",o.getAddress()==null?"":o.getAddress(),"country",o.getCountry()==null?"":o.getCountry(),"state",o.getState()==null?"":o.getState());}
 private Map<String,Object> buildingDto(Building b){return Map.of("id",b.getId(),"organizationId",b.getOrganization().getId(),"name",b.getName(),"type",b.getType()==null?"":b.getType(),"location",b.getLocation()==null?"":b.getLocation(),"areaSqft",b.getAreaSqft()==null?BigDecimal.ZERO:b.getAreaSqft(),"floors",b.getFloors()==null?0:b.getFloors());}
}
